cssCode:
.node-pulse {
  position: absolute;
  width: 20px; height: 20px;
  background: #4facfe; border-radius: 50%;
  box-shadow: 0 0 15px #4facfe;
  animation: pulseNode 3s infinite ease-out;
}
@keyframes pulseNode {
  0% { transform: scale(0.5); box-shadow: 0 0 0 0 rgba(79, 172, 254, 0.7); opacity: 1; }
  100% { transform: scale(2); box-shadow: 0 0 0 40px rgba(79, 172, 254, 0); opacity: 0; }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:transparent;overflow:hidden;';

for(let i=0; i<6; i++) {
  const node = document.createElement('div');
  node.className = 'node-pulse';
  node.style.left = `${10 + Math.random() * 80}%`;
  node.style.top = `${10 + Math.random() * 80}%`;
  node.style.animationDelay = `${Math.random() * 2}s`;
  c.appendChild(node);
}
